import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { createServer } from 'vite';
import ts from 'typescript';
const base = '19b1082b5277b4771dde80b0e7b12f24cac892cf';
const sourcePath = 'src/twin/persistence/state.ts';
const oldSource = execFileSync('git', ['show', `${base}:${sourcePath}`]).toString();
const hash = s => createHash('sha256').update(s).digest('hex');
const before = await fs.readFile(sourcePath, 'utf8');
const virtualOld = '\0review-old-state';
// Only module import paths are adapted to load the exact prior validator body.
const oldLoadable = oldSource.replaceAll("from '../assets/design'", "from '/src/twin/assets/design.ts'").replaceAll("from '../safety'", "from '/src/twin/safety.ts'").replaceAll("from '../types'", "from '/src/twin/types.ts'").replaceAll("from './events'", "from '/src/twin/persistence/events.ts'").replaceAll("from './limits'", "from '/src/twin/persistence/limits.ts'").replaceAll("from './structure'", "from '/src/twin/persistence/structure.ts'");
const oldJavaScript = ts.transpileModule(oldLoadable, { compilerOptions: { target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.ESNext }, fileName: 'review-old-state.ts' }).outputText;
const loader = await createServer({ configFile: false, optimizeDeps: { noDiscovery: true, entries: [] }, plugins: [{ name: 'prior-validator-review', resolveId: id => id === '/review-old-state.ts' ? virtualOld + '.ts' : undefined, load: id => id === virtualOld + '.ts' ? oldJavaScript : undefined }], server: { middlewareMode: true, watch: null, hmr: false, ws: false }, appType: 'custom' });
const cases = [];
try {
  const { buildDesign, DEFAULT_CONFIG } = await loader.ssrLoadModule('/src/twin/assets/design.ts');
  const { initialize, advance } = await loader.ssrLoadModule('/src/twin/engine/simulation.ts');
  const { validateState: current } = await loader.ssrLoadModule('/src/twin/persistence/state.ts');
  const { validateState: prior } = await loader.ssrLoadModule('/review-old-state.ts');
  const design = buildDesign({ ...DEFAULT_CONFIG, requestedAccelerators: 2560 });
  assert.equal(design.modules.length, 2);
  const state = advance(design, initialize(design), 0, [{ id: 'scope-probe-trip', assetId: 'shore/grid', kind: 'trip', timeS: 0 }]);
  assert.ok(state.log.length > 0);
  const ids = design.modules.map(m => m.id);
  const fixtures = [
    ['all valid modules', ids, 'accepted'],
    ['last valid module', [ids.at(-1)], 'accepted'],
    ['empty scope', [], 'accepted'],
    ['duplicate valid module preserves previous admission', [ids[0], ids[0]], 'accepted'],
    ['unknown string', ['unknown-module'], 'STATE_LOG_SCOPE'],
    ['known root asset is not a module', ['shore/grid'], 'STATE_LOG_SCOPE'],
    ['case-different module ID', [ids[0].toUpperCase()], 'STATE_LOG_SCOPE'],
    ['number', [42], 'STATE_LOG_SCOPE'],
    ['null', [null], 'STATE_LOG_SCOPE'],
    ['boolean', [true], 'STATE_LOG_SCOPE'],
    ['plain object', [{}], 'STATE_LOG_SCOPE'],
    ['nested array', [[]], 'STATE_LOG_SCOPE'],
  ];
  for (const [name, scope, expected] of fixtures) {
    const candidate = structuredClone(state); candidate.log[0].affectedIds = scope;
    const original = structuredClone(candidate);
    const check = validator => { try { validator(design, candidate); return 'accepted'; } catch (error) { assert.equal(error.diagnostic?.kind, 'invalid-input'); return error.diagnostic.code; } };
    const priorResult = check(prior), currentResult = check(current);
    assert.equal(priorResult, expected); assert.equal(currentResult, priorResult); assert.deepEqual(candidate, original);
    cases.push({ name, scope, expected, priorResult, currentResult, inputUnchanged: true, status: 'PASS' });
  }
} finally { await loader.close(); }
const after = await fs.readFile(sourcePath, 'utf8');
assert.equal(hash(after), hash(before));
const result = { status: 'PASS', checkedAt: new Date().toISOString(), baselineCommit: base, sourcePath, priorSourceSha256: hash(oldSource), currentSourceSha256: hash(before), sourceUnchangedDuringProbe: true, cases };
await fs.writeFile('artifacts/phase-1-review/scope-optimization-probe.json', JSON.stringify(result, null, 2) + '\n');
console.log(JSON.stringify(result, null, 2));
